def fizz_buzz(n: int) -> int:
    count = 0
    for i in range(n):
        if i % 11 == 0 or i % 13 == 0:
            count += str(i).count('7')
    return count

def is_prime(num: int) -> bool:
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    i = 3
    while i * i <= num:
        if num % i == 0:
            return False
        i += 2
    return True

def prime_fib(n: int) -> int:
    if n <= 0:
        return 0
    count = 0
    a, b = 0, 1
    while True:
        a, b = b, a + b
        if is_prime(a):
            count += 1
            if count == n:
                return a

from typing import List


def triples_sum_to_zero(l: List[int]) -> bool:
    """
    Check if there are three distinct elements
    in the list that sum to zero.

    Examples:
        >>> triples_sum_to_zero([1, 3, 5, 0])
        False
        >>> triples_sum_to_zero([1, 3, -2, 1])
        True
    """
    n = len(l)
    if n < 3:
        return False
    l_sorted = sorted(l)
    for i in range(n - 2):
        if i > 0 and l_sorted[i] == l_sorted[i - 1]:
            continue
        left = i + 1
        right = n - 1
        while left < right:
            current_sum = l_sorted[i] + l_sorted[left] + l_sorted[right]
            if current_sum == 0:
                return True
            elif current_sum < 0:
                left += 1
                while left < right and l_sorted[left] == l_sorted[left - 1]:
                    left += 1
            else:
                right -= 1
                while left < right and l_sorted[right] == l_sorted[right + 1]:
                    right -= 1
    return False

def change_base(x: int, base: int) -> str:
    if x == 0:
        return "0"

    digits = []
    negative = x < 0
    x = abs(x)

    while x > 0:
        digits.append(str(x % base))
        x //= base

    if negative:
        digits.append('-')

    return ''.join(reversed(digits))

def fib4(n: int) -> int:
    if n < 2:
        return 0
    if n == 2:
        return 2
    if n == 3:
        return 0

    a, b, c, d = 0, 0, 2, 0
    for _ in range(4, n + 1):
        a, b, c, d = b, c, d, a + b + c + d

    return d

def decode_shift(s: str) -> str:
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            shifted = ord(ch) - 5
            if shifted < ord('a'):
                shifted += 26
            result.append(chr(shifted))
        else:
            result.append(ch)
    return ''.join(result)

def remove_vowels(text: str) -> str:
    vowels = "aeiouAEIOU"
    return "".join(char for char in text if char not in vowels)

def fib(n: int) -> int:
    if n <= 0:
        return 0
    a, b = 0, 1
    for _ in range(n - 1):
        a, b = b, a + b
    return b

def correct_bracketing(brackets: str) -> bool:
    balance = 0
    for char in brackets:
        if char == '<':
            balance += 1
        elif char == '>':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def sum_to_n(n: int) -> int:
    if n <= -1:
        return 0
    return n * (n + 1) // 2 + 1

def correct_bracketing(brackets: str) -> bool:
    balance = 0
    for char in brackets:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def fibfib(n: int) -> int:
    if n == 0 or n == 1:
        return 0
    if n == 2:
        return 1
    a, b, c = 0, 0, 1
    for _ in range(3, n + 1):
        a, b, c = b, c, a + b + c
    return c

def vowels_count(s: str) -> int:
    vowels = set('aeiou')
    s = s.strip().lower()
    if not s:
        return 0
    count = 0
    for i, ch in enumerate(s):
        if ch in vowels:
            count += 1
        elif ch == 'y' and i == len(s) - 1 and s[i].isalpha():
            count += 1
    return count

from typing import List


def pluck(arr: List[int]) -> List[int]:
    """
    Return the smallest even value and its index from the given array.

    Args:
        arr: List of integers representing tree branch nodes.

    Returns:
        List containing [smallest_even_value, index] if found, otherwise [].
    """
    if not arr:
        return []

    smallest_value = None
    smallest_index = None

    for i, value in enumerate(arr):
        if value % 2 == 0:
            if smallest_value is None or value < smallest_value:
                smallest_value = value
                smallest_index = i
            elif value == smallest_value and i < smallest_index:
                smallest_index = i

    if smallest_value is None:
        return []

    return [smallest_value, smallest_index]

def triangle_area(a: int, b: int, c: int) -> float:
    if a + b > c and a + c > b and b + c > a:
        s = (a + b + c) / 2
        area = (s * (s - a) * (s - b) * (s - c)) ** 0.5
        return round(area, 2)
    else:
        return -1.0

from typing import List

def total_match(lst1: List[str], lst2: List[str]) -> List[str]:
    total1 = sum(len(s) for s in lst1)
    total2 = sum(len(s) for s in lst2)

    if total1 <= total2:
        return lst1
    else:
        return lst2

def is_multiply_prime(a: int) -> bool:
    """
    Check if the given number is the multiplication of 3 prime numbers.

    Constraints:
        The three prime numbers must be <= 100.

    Example:
        is_multiply_prime(30) == True
        30 = 2 * 3 * 5
    """
    if a <= 0:
        return False

    # Generate primes up to 100
    primes = []
    for num in range(2, 101):
        is_prime = True
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(num)

    # Check all combinations of 3 primes
    n = len(primes)
    for i in range(n):
        for j in range(i, n):
            for k in range(j, n):
                if primes[i] * primes[j] * primes[k] == a:
                    return True
    return False

def is_multiply_prime(a: int) -> bool:
    """
    Check if the given number is the multiplication of 3 prime numbers.

    Constraints:
        The three prime numbers must be <= 100.

    Example:
        is_multiply_prime(30) == True
        30 = 2 * 3 * 5
    """
    if a <= 1:
        return False

    # Generate primes up to 100 using Sieve of Eratosthenes
    limit = 100
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(limit ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, limit + 1, i):
                is_prime[j] = False
    primes = [i for i, prime in enumerate(is_prime) if prime]

    # Check all combinations of three primes
    n = len(primes)
    for i in range(n):
        for j in range(i, n):
            for k in range(j, n):
                if primes[i] * primes[j] * primes[k] == a:
                    return True
    return False

def is_simple_power(x: int, n: int) -> bool:
    if n == 1:
        return x == 1
    if x == 1:
        return True
    power = 0
    current = 1
    while current <= x:
        if current == x:
            return True
        power += 1
        current = n ** power
    return False

def iscube(a: int) -> bool:
    if a == 0:
        return True
    if a > 0:
        return round(a ** (1/3)) ** 3 == a
    else:
        return round((-a) ** (1/3)) ** 3 == -a

def hex_key(num: str) -> int:
    primes = {'2', '3', '5', '7', 'B', 'D'}
    return sum(1 for digit in num if digit in primes)

def is_happy(s: str) -> bool:
    if len(s) < 3:
        return False
    for i in range(len(s) - 2):
        if s[i] == s[i + 1] or s[i] == s[i + 2] or s[i + 1] == s[i + 2]:
            return False
    return True

"""
Convert numerical GPAs to letter grades according to a specific grading scale.
"""

from typing import List


def numerical_letter_grade(grades: List[float]) -> List[str]:
    """
    Convert a list of numerical GPAs to letter grades based on a predefined scale.

    The GPA is rounded to one decimal place (half up) before conversion.
    Grades outside the valid range (0.0 to 4.0) return an empty string.

    Args:
        grades: A list of float values representing GPAs.

    Returns:
        A list of strings representing the corresponding letter grades.
    """
    letter_grades = []

    for gpa in grades:
        # Handle out-of-bounds grades
        if gpa < 0.0 or gpa > 4.0:
            letter_grades.append('')
            continue

        # Round to one decimal place (half up)
        rounded_gpa = round(gpa, 1)

        # Determine letter grade based on thresholds
        if rounded_gpa == 4.0:
            letter_grades.append('A+')
        elif rounded_gpa > 3.7:
            letter_grades.append('A')
        elif rounded_gpa > 3.3:
            letter_grades.append('A-')
        elif rounded_gpa > 3.0:
            letter_grades.append('B+')
        elif rounded_gpa > 2.7:
            letter_grades.append('B')
        elif rounded_gpa > 2.3:
            letter_grades.append('B-')
        elif rounded_gpa > 2.0:
            letter_grades.append('C+')
        elif rounded_gpa > 1.7:
            letter_grades.append('C')
        elif rounded_gpa > 1.3:
            letter_grades.append('C-')
        elif rounded_gpa > 1.0:
            letter_grades.append('D+')
        elif rounded_gpa > 0.7:
            letter_grades.append('D')
        elif rounded_gpa > 0.0:
            letter_grades.append('D-')
        else:
            letter_grades.append('E')

    return letter_grades
